{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "In non-human primates, sacubitril showed very low CNS exposure (CSF:plasma ≤0.0044, brain:plasma ≤0.0326), indicating that this peptidomimetic prodrug does not meaningfully cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Merck-3, a hydroxyethylamine peptidomimetic with benzyl and amide functionalities, had brain concentrations below the detection limit after IV dosing and was a P-gp substrate, directly demonstrating poor brain penetration for a scaffold similar to the query's hydroxyethylene/benzyl/amide core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Carfilzomib, a peptide-based proteasome inhibitor with multiple aromatic and amide groups, did not suppress brain proteasome activity after IV administration, indicating poor BBB crossing for peptide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "HIV protease inhibitor peptidomimetics such as amprenavir do not reach sufficient CSF concentrations, supporting poor CNS access for this class of peptidomimetic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Inhibitor 6, a smaller hydroxyethylamine BACE inhibitor, achieved a brain/plasma ratio of 0.69 and appreciable brain exposure, showing that some related scaffolds can penetrate; however, the query is larger and more peptide-like.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "PPI-1019, a peptide, reached the brain rapidly after IV administration in humans, providing a contradictory example of CNS access for a peptide; its low similarity limits transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly functionalized peptidomimetic with a hydroxyethylene isostere, two benzyl groups, multiple amides, a hydroxyl, and a cyclic urea. Direct in vivo evidence from related peptidomimetic protease inhibitors (sacubitril, Merck-3, carfilzomib, amprenavir) consistently shows very low CSF/brain exposure and P-gp efflux, outweighing isolated examples of brain-penetrant analogues. Prediction: fail.",
  "evidence_gaps": [
    "No direct experimental brain/CSF data for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.29), limiting quantitative transfer.",
    "P-gp/BCRP efflux status of the query is unknown.",
    "Human CNS exposure and unbound brain concentrations were not measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

